 72	// Generate strictly decodes an authoring catalog, resolves its anchors beneath
 73	// root, and returns a deterministic, line-oriented artifact wire catalog.
 74	func Generate(root string, data []byte, limits Limits) ([]byte, error) {
 75		compiled, err := Compile(root, data, limits, nil)
 76		if err != nil {
 77			return nil, err
 78		}
 79		out, err := encodeCatalog(compiled.Catalog)
 80		if err != nil {
 81			return nil, fmt.Errorf("encode artifact catalog: %w", err)
 82		}
 83		return out, nil
 84	}
