146	func decodeAuthoring(data []byte, limits Limits) (*AuthoringCatalog, Limits, error) {
147		normalized, err := normalizeLimits(limits)
148		if err != nil {
149			return nil, limits, err
150		}
151		if len(data) > normalized.Bytes {
152			return nil, limits, failure("$", "byte limit exceeded")
153		}
154		if !utf8.Valid(data) {
155			return nil, limits, failure("$", "invalid UTF-8")
156		}
157		if err := checkEscapes(data); err != nil {
158			return nil, limits, err
159		}
160		decoder := json.NewDecoder(bytes.NewReader(data))
161		decoder.UseNumber()
162		if err := scan(decoder, 0, normalized.Depth); err != nil {
163			return nil, limits, err
164		}
165		if _, err := decoder.Token(); err != io.EOF {
166			return nil, limits, failure("$", "trailing JSON or invalid syntax")
167		}
168		if err := checkShape(data, reflect.TypeOf(AuthoringCatalog{}), "$"); err != nil {
169			return nil, limits, err
170		}
171		var doc AuthoringCatalog
172		if err := json.Unmarshal(data, &doc); err != nil {
173			return nil, limits, failure("$", "invalid field type")
174		}
175		if doc.Version != AuthoringVersion {
176			return nil, limits, failure("$.version", "unsupported version")
177		}
178		return &doc, normalized, nil
179	}
180	
260		for i, anchor := range doc.SourceAnchors {
261			if !used[anchor.ID] {
262				return nil, fmt.Errorf("$.source_anchors[%d]: unused source anchor", i)
263			}
264		}
265		return catalog, nil
266	}
